import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec(torch::Tensor A, torch::Tensor B);
"""

matvec_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>
#include <cuda_pipeline_primitives.h>
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
#define MATVEC_CP_ASYNC 1
#else
#define MATVEC_CP_ASYNC 0
#endif
#include <cute/tensor.hpp>
using namespace cute;
// C[m] = sum_k A[m,k] * B[k]
// A: (M,K) row-major contiguous, B: (K,) contiguous, C: (M,)
// CTA tiling over the output rows (M-tiling) + split-K: each CTA
// computes RowsPerCTA consecutive output rows for one K-slice. The B
// slice is staged chunk by chunk into shared memory, so each B element
// is fetched from global memory once per CTA instead of once per row,
// while the A rows are streamed with vectorized 16B loads through CUTE
// global-memory tensors. This amortizes B traffic across the rows of a
// tile and raises the compute-per-byte ratio of this memory-bound
// reduction. Kc stays a multiple of 4 so every (row, slice) base is
// 16-byte aligned on the float4 path.
template <int BlockSize, int RowsPerCTA, int ChunkV>
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K, int Kc)
{
  const int m0    = blockIdx.x * RowsPerCTA;
  const int slice = blockIdx.y;
  const int tid   = threadIdx.x;
  // Split-K: this block covers [kStart, kStart + kLen) of the reduction.
  const int kStart = slice * Kc;
  const int kLen   = min(K - kStart, Kc);
  const float* aBase = A + (int64_t)m0 * (int64_t)K + kStart;
  const float* bSl   = B + kStart;
  float acc[RowsPerCTA];
  #pragma unroll
  for (int r = 0; r < RowsPerCTA; ++r) acc[r] = 0.0f;
  // Kc % 4 == 0 and K % 4 == 0 keep every (row, slice) base 16B aligned.
  const bool vecOk = ((K & 3) == 0) &&
                     ((reinterpret_cast<uintptr_t>(A) & 0xF) == 0) &&
                     ((reinterpret_cast<uintptr_t>(B) & 0xF) == 0);
  if (vecOk) {
    const int Kv = kLen >> 2;  // number of float4 elements in this slice
#if MATVEC_CP_ASYNC
    // Two-stage cp.async pipeline over the shared-memory B chunks: while
    // the CTA streams all RowsPerCTA rows of A against the chunk already
    // resident in shared memory, the next chunk is fetched in the
    // background with asynchronous 16B copies, overlapping global-memory
    // latency with compute instead of serializing load/sync/compute.
    __shared__ float4 sB[2][ChunkV];
    Tensor gBv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(bSl)),
                             make_shape(Kv), make_stride(Int<1>{}));
    const float4* aVec[RowsPerCTA];
    #pragma unroll
    for (int r = 0; r < RowsPerCTA; ++r)
      aVec[r] = reinterpret_cast<const float4*>(aBase + (int64_t)r * (int64_t)K);
    // Prologue: asynchronously stage chunk 0 into buffer 0.
    const int cLen0 = min(ChunkV, Kv);
    for (int i = tid; i < cLen0; i += BlockSize)
      __pipeline_memcpy_async(&sB[0][i], &gBv(i), sizeof(float4));
    __pipeline_commit();
    int buf = 0;
    for (int c0 = 0; c0 < Kv; c0 += ChunkV) {
      const int cLen = min(ChunkV, Kv - c0);
      const int cN = c0 + ChunkV;
      // Prefetch the next chunk into the other buffer, then wait until
      // the current chunk's asynchronous copy has completed.
      if (cN < Kv) {
        const int cLenN = min(ChunkV, Kv - cN);
        for (int i = tid; i < cLenN; i += BlockSize)
          __pipeline_memcpy_async(&sB[buf ^ 1][i], &gBv(cN + i), sizeof(float4));
        __pipeline_commit();
        __pipeline_wait_prior(1);
      } else {
        __pipeline_wait_prior(0);
      }
      __syncthreads();
      // Stream all RowsPerCTA rows of A against the resident B chunk;
      // fully coalesced vectorized loads through CUTE global tensors.
      for (int i = tid; i < cLen; i += BlockSize) {
        const float4 b = sB[buf][i];
        #pragma unroll
        for (int r = 0; r < RowsPerCTA; ++r) {
          if (m0 + r < M) {
            Tensor gAv = make_tensor(make_gmem_ptr(aVec[r]),
                                     make_shape(Kv), make_stride(Int<1>{}));
            const float4 a = gAv(c0 + i);
            acc[r] = fmaf(a.x, b.x, fmaf(a.y, b.y, fmaf(a.z, b.z, fmaf(a.w, b.w, acc[r]))));
          }
        }
      }
      __syncthreads();
      buf ^= 1;
    }
#else
    __shared__ float4 sB[ChunkV];
    Tensor gBv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(bSl)),
                             make_shape(Kv), make_stride(Int<1>{}));
    const float4* aVec[RowsPerCTA];
    #pragma unroll
    for (int r = 0; r < RowsPerCTA; ++r)
      aVec[r] = reinterpret_cast<const float4*>(aBase + (int64_t)r * (int64_t)K);
    for (int c0 = 0; c0 < Kv; c0 += ChunkV) {
      const int cLen = min(ChunkV, Kv - c0);
      for (int i = tid; i < cLen; i += BlockSize) sB[i] = gBv(c0 + i);
      __syncthreads();
      for (int i = tid; i < cLen; i += BlockSize) {
        const float4 b = sB[i];
        #pragma unroll
        for (int r = 0; r < RowsPerCTA; ++r) {
          if (m0 + r < M) {
            Tensor gAv = make_tensor(make_gmem_ptr(aVec[r]),
                                     make_shape(Kv), make_stride(Int<1>{}));
            const float4 a = gAv(c0 + i);
            acc[r] = fmaf(a.x, b.x, fmaf(a.y, b.y, fmaf(a.z, b.z, fmaf(a.w, b.w, acc[r]))));
          }
        }
      }
      __syncthreads();
    }
#endif
  } else {
    // Generic scalar fallback (still coalesced, row-tiled).
    for (int k = tid; k < kLen; k += BlockSize) {
      const float b = bSl[k];
      #pragma unroll
      for (int r = 0; r < RowsPerCTA; ++r) {
        if (m0 + r < M)
          acc[r] = fmaf(aBase[(int64_t)r * (int64_t)K + k], b, acc[r]);
      }
    }
  }
  // Warp + shared-memory tree reduction, one pass per row of the tile.
  constexpr int NumWarps = BlockSize / 32;
  __shared__ float sPart[RowsPerCTA][NumWarps];
  const int lane = tid & 31;
  const int wid  = tid >> 5;
  #pragma unroll
  for (int r = 0; r < RowsPerCTA; ++r) {
    float sum = acc[r];
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1)
      sum += __shfl_down_sync(0xffffffffu, sum, off);
    if (lane == 0) sPart[r][wid] = sum;
  }
  __syncthreads();
  if (wid == 0) {
    #pragma unroll
    for (int r = 0; r < RowsPerCTA; ++r) {
      float v = (lane < NumWarps) ? sPart[r][lane] : 0.0f;
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1)
        v += __shfl_down_sync(0xffffffffu, v, off);
      // Combine this slice's partial dot products across split-K blocks.
      const int m = m0 + r;
      if (lane == 0 && m < M) atomicAdd(&C[m], v);
    }
  }
}
torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A must be (M,K), B must be (K,1)");
  TORCH_CHECK(B.size(1) == 1, "B must have shape (K,1)");
  TORCH_CHECK(A.size(1) == B.size(0), "inner dimensions must match");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  const int64_t M = A_c.size(0);
  const int64_t K = A_c.size(1);
  TORCH_CHECK(M > 0 && K > 0, "M and K must be positive");
  TORCH_CHECK(M < (int64_t)INT32_MAX && K < (int64_t)INT32_MAX,
